s_forged() {
  stage "Forged requests (E1)"
  say "The wizard needs one real form request from A to change. Open DevTools > Network in A's window."
  step "Open Study settings. Set the goal score to 163 and save."
  step "In Network, find the POST to /settings (it has a Next-Action header). Right-click > Copy > Copy as cURL (bash)."
  capture_curl settings
  ask_cookie a
  local dir="$RUN_DIR/forged" codes=() out
  mkdir -p "$dir"
  local origin_line="s{(-H '[Oo]rigin: )\Q$COPY\E'}{\${1}https://forged.example'}"
  local no_origin="s{ *-H '[Oo]rigin: [^']*' *\\\\?\n?}{}"
  local wrong_type="s{(-H '[Cc]ontent-[Tt]ype: )[^']*'}{\${1}application/x-www-form-urlencoded'}"
  local goal_170="s{(--data-raw .*?)(?:(?<=\\\\n)|(?<![0-9A-Za-z_]))163(?![0-9])}{\${1}170}s"
  replay settings "$dir/wrong-origin" "$origin_line; $goal_170"
  replay settings "$dir/no-origin" "$no_origin; $goal_170"
  replay settings "$dir/wrong-type" "$wrong_type; $goal_170"
  record "7a Server Action" "wrong Origin HTTP $(status_of "$dir/wrong-origin"), no Origin HTTP $(status_of "$dir/no-origin"), wrong type HTTP $(status_of "$dir/wrong-type") (expected 403, 403, 415)"
  out="$dir/scan-wrong-origin"
  codes+=("scan wrong Origin $(curl -sS -o "$out.body" -w '%{http_code}' -H 'Origin: https://forged.example' -H "@$RUN_DIR/cookie-a" -F "image=@$PT_SCREENSHOT" "$COPY/api/practice-test/extract" || printf 000)")
  codes+=("scan no Origin $(curl -sS -o "$out.body" -w '%{http_code}' -H "@$RUN_DIR/cookie-a" -F "image=@$PT_SCREENSHOT" "$COPY/api/practice-test/extract" || printf 000)")
  codes+=("scan JSON $(curl -sS -o "$out.body" -w '%{http_code}' -H "Origin: $COPY" -H "@$RUN_DIR/cookie-a" -H 'Content-Type: application/json' --data '{}' "$COPY/api/practice-test/extract" || printf 000)")
  codes+=("students form $(curl -sS -o "$out.body" -w '%{http_code}' -H "Origin: $COPY" -H "@$RUN_DIR/cookie-admin" -H 'Content-Type: text/plain' --data 'x' "$COPY/api/students" || printf 000)")
  record "7b routes" "$(IFS=,; printf '%s' "${codes[*]}") (expected 403, 403, 415, 415)"
  show_sql "SELECT s.goal_score,
  (SELECT count(*) FROM running_scans) AS running_scans,
  (SELECT string_agg(result || ' ' || route || ' ' || n, ', ' ORDER BY result, route) FROM (
    SELECT result, route, count(*) AS n FROM security_log
    WHERE event = 'forged_request_refused' AND logged_at > now() - interval '15 minutes' GROUP BY result, route) x) AS refusals
FROM students s JOIN accounts a ON a.id = s.account_id WHERE a.email = '$(addr a)';"
  note "Expected: 163 (no forged save), 0, and noOrigin 2, wrongOrigin 2, wrongContentType 3, on /settings, /api/practice-test/extract, /api/students."
  paste_result "7c no write, logged"
  replay settings "$dir/same-site" "$goal_170"
  record "7d same-site" "HTTP $(status_of "$dir/same-site") (expected 200). Server Action reply Cache-Control: $(header_of "$dir/same-site" cache-control)"
  show_sql "SELECT s.goal_score FROM students s JOIN accounts a ON a.id = s.account_id WHERE a.email = '$(addr a)';"
  ask_result "7e same-site saved" "Expected 170. What did it show?"
  pause
}

