s_slow_reply() {
  stage "30-second slow reply (Stage 5 carry)"
  say "The copy will send one scan to a server on this Mac that accepts the connection and never answers."
  say "A free Cloudflare tunnel gives that server a public address. Only this Mac sees the request."
  if ! command -v cloudflared > /dev/null; then
    step "Install the tunnel tool: brew install cloudflared"
    pause "When cloudflared is installed, press Enter"
  fi
  local port=8736 tunnel_url="" tries
  cat > "$RUN_DIR/silent.py" <<PY
import socket
s = socket.socket()
s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
s.bind(("127.0.0.1", $port))
s.listen(16)
held = []
while True:
    held.append(s.accept()[0])
PY
  python3 "$RUN_DIR/silent.py" & local silent_pid=$!
  cloudflared tunnel --no-autoupdate --url "http://127.0.0.1:$port" > "$RUN_DIR/tunnel.log" 2>&1 & local tunnel_pid=$!
  for tries in $(seq 1 30); do
    tunnel_url=$(grep -oE 'https://[a-z0-9-]+\.trycloudflare\.com' "$RUN_DIR/tunnel.log" | head -n1 || true)
    [[ -n "$tunnel_url" ]] && break
    sleep 1
  done
  if [[ -z "$tunnel_url" ]]; then
    warn "The tunnel did not start. See $RUN_DIR/tunnel.log."
    kill "$silent_pid" "$tunnel_pid" 2>/dev/null || true
    record "10 slow reply" "Not run: the tunnel did not start"; pause; return
  fi
  sleep 5
  local probe
  probe=$(curl -s -o /dev/null -m 8 -w '%{http_code}' "$tunnel_url/v1/messages" || true)
  say "Tunnel: $tunnel_url (a probe got '${probe:-no answer}' in 8 seconds; expected no answer, 000)"
  printf '%s' "$tunnel_url" | pbcopy
  open_url "https://vercel.com/dashboard"
  step "COPY project > Settings > Environment Variables. Add ANTHROPIC_BASE_URL on Production only, value: the tunnel address (copied)."
  redeploy_copy DEPLOYMENT_SLOW
  local result out="$RUN_DIR/slow"
  say "Sending one practice-test scan as A. It should stop after about 30 seconds…"
  result=$(scan a /api/practice-test/extract "$PT_SCREENSHOT" "$out")
  record "10a slow reply" "$DEPLOYMENT_SLOW: HTTP ${result% *} after ${result#* } s, text '$(grep -oF "$TOO_LONG_TEXT" "$out.body" | head -n1)' (expected 504 after 30 to 32 s)"
  kill "$tunnel_pid" "$silent_pid" 2>/dev/null || true
  step "Delete ANTHROPIC_BASE_URL from copy Production."
  redeploy_copy DEPLOYMENT
  record "10b setting removed" "ANTHROPIC_BASE_URL deleted. Copy back on $DEPLOYMENT"
  step "Anthropic Console > the copy's workspace > Logs: check for a request at that time."
  ask_result "10c no Anthropic call" "Expected no request. What did the Console show?"
  pause
}

