  show_sql "SELECT a.id AS account_id, s.id AS student_id FROM accounts a JOIN students s ON s.account_id = a.id WHERE a.email = '$(addr c)';"
  ask_uuid C_ACCOUNT_ID "C's account_id (kept in the run folder only):"
